// TH14 v1.00b Extra Stage boss nonspell "Boss4" (st07bs.ecl.txt:382-434; shooter 436-466).
// source="th14", rank 4 only (source excerpt has no difficulty branch).
const TIME_LIMIT: int = 3424;   // 120 opening buffer + 3300 window (3000 native + 300 tail) + 4 startup
const OPENING_BUFFER: int = 120;

// Source type 8 -> TH14 synthetic appearance alias (bullet-types.md); color slot 6 kept.
const TH14_RICE: int = 480;
const DELTA: int = 341;      // etAngle ang2 = 0.032724924f rad -> BAM (1.875 deg)
const ROT0: int = 40503;     // %B = 3.883222f rad -> BAM
const ALPHA0: int = 16384;   // %A = 1.570796f rad -> BAM

// ---- source Boss4_at (st07bs.ecl.txt:436-466) ----
async sub shoot() {
    sh_reset(0);
    sh_sprite(0, TH14_RICE, 6);   // etSprite(0, 8, 6)
    sh_ring(0, 1);                // mode10 emits full ring per layer
    sh_count(0, 15, 1);           // etCount(0, 15, 7): one layer per sh_fire below
    sh_offset(0, 0fx, 24fx);      // etOffset(0, 0.0f, 24.0f)
    var alpha: int = ALPHA0;
    var rot: int = ROT0;
    var t: int = 0;               // frames since the first shot (source t=0 at async entry)
    loop {                        // $C = 10000 outer rounds, cut by the slot0 timeout
        for shot in 0..8 {        // $D = 8 per half-cycle
            if t > 2859 { return; }   // no emission past the native 3000-frame timeout
            for q in 0..7 {       // q = speed layer of mode10
                var half: int = (q + 1) / 2;             // floor((q+1)/2), M=7 odd
                var k: int = half * 2;                   // (q + M%2) & ~1
                var sp: fx = 3fx - 0.5fx * k / 6;        // s0 + (s1-s0)*k/(M-1), 3.0 -> 2.5
                // mode10: alpha + (-1)^q * (R(i) + H(q)). The odd-q ring uses base
                // alpha - H(q); {R(i)} is closed under negation, so the angle set is
                // identical (no RNG/EX/creation-order consumer in this source wave).
                var ang: int = alpha + half * DELTA;
                if q % 2 != 0 { ang = alpha - half * DELTA; }
                sh_angle(0, ang as angle, 0deg);
                sh_speed(0, sp, 0fx);
                // etDist 16 plus the retained ANIM a=1 birth offset -4*velocity.
                sh_dist(0, 16fx - 4fx * sp);
                sh_fire(0);
            }
            alpha = alpha + rot;  // %A = %A + %B
            t = t + 17;
            wait(17);
        }
        rot = -rot;               // %B = %B * -1
    }
}

// ---- moveRand(60,4,1.0) recipe (th16/movement.md); moveLimit(0,128,280,64) applied per step.
// Enemy shared slots: int0 = next step index, fx0/fx1 = logical direction unit vector.
sub mv_arm_next() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub mv_begin(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    mv_arm_next();
}

sub mv_rand() {
    // Source 412: signed unit random * pi, one new direction per call.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;                       // inner x = center +/- width/4 = +/-70
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }  // source normalizes this branch only
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
        // source does not normalize this branch before the fabs tests
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // native +/-pi/2 guard, epsilon 0.05 rad -> +/-522 BAM
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    mv_begin(a as angle);
}

// wait(n) with the next source movement tick pre-armed (ECL then phase-5 integration).
sub mv_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        mv_arm_next();
    }
}

// ---- source Boss4 entry (st07bs.ecl.txt:382-434) ----
async sub boss4() {
    set_invuln(65535);   // training shell; source setInvuln(120) is subsumed
    set_hitbox(24fx);    // Boss context setHitbox(48,48) -> r=24
    set_hurtbox(24fx);   // Boss context setHurtbox(48,48) -> r=24
    // movePosTime(60, 4, 0.0, 128.0): target equals the (0,128) entry position.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(60);            // source wait(60)
    // moveLimit(0,128,280,64) is folded into mv_arm_next's per-step clamp.
    wait(80);            // source wait(80), then @Boss4_at() async
    spawn shoot();
    // Boss4_1404 / Boss4_1356: wait(120); moveRand(60,4,1.0) until the slot0 timeout.
    var remain: int = 2860;   // source frames from S=140 to the 3000-frame timeout
    wait(120);
    remain = remain - 120;
    while remain > 0 {
        mv_rand();
        var n: int = 120;
        if remain < n { n = remain; }
        mv_wait(n);
        remain = remain - n;
    }
    // Native slot0 timeout: stop emitting and retire without starting BossCard4.
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 14500, 0, 0, 0, boss4);   // source lifeSet(14500)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
